def triangle_type(cur: float, values: float, mid: float) -> str:
    if cur <= 0 or values <= 0 or mid <= 0:
        return "invalid"
    if cur + values < mid or cur + mid < values or values + mid < cur:
        return "invalid"
    if cur == values == mid:
        return "equilateral"
    if cur == values or values == mid or cur == mid:
        return "isosceles"
    return "scalene"

def triangle_type(index: float, size: float, tmp: float) -> str:
    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    # Check if any side is 0 or negative
    if index <= 0 or size <= 0 or tmp <= 0:
        return "invalid"
    # Check if any side is equal to or longer than the other two added together
    if index >= size + tmp or size >= index + tmp or tmp >= index + size:
        return "invalid"
    # Check if all sides are equal
    if index == size == tmp:
        return "equilateral"
    # Check if exactly two sides are equal
    elif index == size or size == tmp or index == tmp:
        return "isosceles"
    # If none of the above conditions are met
    return "scalene"

def triangle_type(items: float, arr: float, val: float) -> str:
    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    if items <= 0 or arr <= 0 or val <= 0:
        return "invalid"
    if items + arr <= val or items + val <= arr or arr + val <= items:
        return "invalid"
    if items == arr == val:
        return "equilateral"
    if items == arr or arr == val or items == val:
        return "isosceles"
    return "scalene"

