def group_anagrams(item: list[str]) -> list[list[str]]:
    # Create a dictionary to hold the list of words for each anagram group
    idx = {}

    # Iterate over each word in the list
    for i in item:
        # Sort the characters in the word to create a key for anagram groups
        total = ''.join(sorted(i))

        # If the sorted word is already a key in the dictionary, append the word to the group
        if total in idx:
            idx[total].append(i)
        # Otherwise, create a new key-value pair in the dictionary with the sorted word and the word as the value
        else:
            idx[total] = [i]

