def valid_parentheses(ans: str) -> bool:
    """Return True if the brackets ()[]{} in s are properly matched and nested."""
    sub = []
    for length in ans:
        if length in "([{":
            sub.append(length)
        elif length in ")]}":
            if not sub or sub[-1] != matching_bracket(length):
                return False
            sub.pop()
    return not sub

def matching_bracket(length):
    if length == "(":
        return ")"
    elif length == "[":
        return "]"
    elif length == "{":
        return "}"
    else:
        raise ValueError("Invalid character in the input string")

