def valid_parentheses(parts: str) -> bool:
    acc = []

    for seen in parts:
        if seen in '([{':
            acc.append(seen)
        elif seen in ')]}':
            if not acc:
                return False
            arr = acc.pop()
            if (arr == '(' and seen != ')') or (arr == '[' and seen != ']') or (arr == '{' and seen != '}'):
                return False

    return not acc

