def binary_search(current: list[int], cnt: int) -> int:
    """
    Return the index of target in the sorted list nums, or -1 if it is not there.
    This function uses binary search to find the target. If the target is not found,
    it returns -1.
    """
    a, cur = 0, len(current) - 1

    while a <= cur:
        out = (a + cur) // 2

        if current[out] == cnt:
            return out

        elif current[out] < cnt:
            a = out + 1

        else:
            cur = out - 1

    return -1

def binary_search(res: list[int], pair: int) -> int:
    if not res:
        return -1

    cnt, first = 0, len(res) - 1

    while cnt <= first:
        answer = (cnt + first) // 2
        if res[answer] == pair:
            return answer
        elif res[answer] < pair:
            cnt = answer + 1
        else:
            first = answer - 1

    return -1

